import json, sys
sys.path.insert(0, 'lib'); import normalize
SNIP = normalize.SNIPPET
BASE = "https://freya-final-mock.yasir-freya.workers.dev/voice/v1/"
H = {"type":"object","properties":{"Content-Type":{"type":"string","default":"application/json"},"Accept":{"type":"string","default":"application/json"}}}
CALL = {"type":"object","properties":{"ani":{"type":"string","default":"{{customerNumber}}"},"lang":{"type":"string","default":"tr"}}}
def api(name, path, data, desc):
    props = {k:{"type":"string","default":v,"description":k} for k,v in data.items()}
    return {"type":"function","config":{"timeoutMs":20000,"maxRetries":1},"function":{"name":name,"handler":"__function__:api_call","description":desc,
      "parameters":{"type":"object","properties":{"url":{"type":"string","default":BASE+path},"method":{"type":"string","default":"POST"},"headers":H,
      "body":{"type":"object","properties":{"data":{"type":"object","properties":props},"call":CALL}}}}}}
def C(*conds): return {"logic":"or","conditions":list(conds)}
def eq(v,o): return {"variable":v,"operator":"equals","operand":o}
def gt(v,o): return {"variable":v,"operator":"greater_than","operand":o}
ALW = {"operator":"always"}
def T(t,d,c): return {"target_node":t,"description":d,"condition":c}
nodes = {}
def end(n, msg):
    nodes[n] = {"name":n,"node_type":"end_call","on_enter":{"type":"silent"},"disable_inactivity_monitor":True,"transitions":[],
      "terminal":{"type":"function","function":{"name":n,"handler":"__function__:end_call","description":"End the call.",
      "parameters":{"type":"object","properties":{"message_mode":{"type":"string","default":"custom"},"spoken_message":{"type":"string","default":msg}}}}}}
def apin(n, tool, nxt, err, tts=None):
    nodes[n] = {"name":n,"node_type":"api_request","passthrough":True,"passthrough_default_transition":nxt,
      "on_enter":{"type":"tts","text":tts} if tts else {"type":"silent"},"disable_inactivity_monitor":True,"pre_actions":[tool],
      "transitions":[T(err,"call failed",C(gt(n+"_failure_count",0))), T(nxt,"always",ALW)]}
def code(n, src, trans, tts=None):
    nodes[n] = {"name":n,"node_type":"code","passthrough":True,"passthrough_default_transition":trans[-1]["target_node"],
