    return out
MON = ['Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık']
DW = ['sıfır','bir','iki','üç','dört','beş','altı','yedi','sekiz','dokuz']
def trdate(s):
    try:
        s = str(s)[:10]
        y, m, d = s.split('-')
        return str(int(d)) + ' ' + MON[int(m)-1] + ' ' + y
    except Exception:
        return str(s)
def digw(s):
    return ' '.join(DW[int(c)] for c in str(s) if c.isdigit())
def num(v):
    try:
        return float(str(v).replace(',', '.'))
    except Exception:
        return None
def amt(v):
    f = num(v)
    if f is None:
        return str(v)
    s = ('%.2f' % f)
    i, k = s.split('.')
    i2 = ''
    while len(i) > 3:
        i2 = '.' + i[-3:] + i2
        i = i[:-3]
    i = i + i2
    return i if k == '00' else i + ',' + k
'''

